package day02;

public class Problem2_UpDownGame {
    public static void main(String[] args) {
        int answer = 73;
        int[] guesses = {50, 80, 65, 75, 73};

        int maxAttempts = 5;
        int attempt = 0;
        boolean isSuccess = false;

        System.out.println("=== 업앤다운(UP & DOWN) 숫자 맞추기 게임 ===");
        System.out.printf("목표: 1부터 100 사이의 숫자를 맞춰보세요! (최대 %d회 기회)\n\n", maxAttempts);

        while (attempt < maxAttempts) {
            int currentGuess = guesses[attempt];
            attempt++;

            System.out.printf("[시도 %d/%d] 입력값: %d -> ", attempt, maxAttempts, currentGuess);

            if (currentGuess < answer) {
                System.out.println("🔺 UP! 더 큰 숫자입니다.");
            } else if (currentGuess > answer) {
                System.out.println("🔻 DOWN! 더 작은 숫자입니다.");
            } else {
                System.out.println("🎯 정답입니다! 축하합니다!");
                isSuccess = true;
                break;
            }
        }

        System.out.println("---------------------------------");
        if (isSuccess) {
            System.out.printf("게임 종료: %d회 시도 만에 승리하셨습니다!\n", attempt);
        } else {
            System.out.printf("게임 종료: 기회를 모두 소진하셨습니다. (정답은 %d였습니다)\n", answer);
        }
    }
}

