package day03;

import java.util.Random;

public class Problem2_LottoGenerator {
    public static void main(String[] args) {
        int[] lottoNumbers = new int[6];
        Random rand = new Random(42);

        int count = 0;
        while (count < 6) {
            int num = rand.nextInt(45) + 1;
            boolean isDuplicate = false;
            for (int i = 0; i < count; i++) {
                if (lottoNumbers[i] == num) {
                    isDuplicate = true;
                    break;
                }
            }
            if (!isDuplicate) {
                lottoNumbers[count++] = num;
            }
        }

        for (int i = 0; i < lottoNumbers.length - 1; i++) {
            for (int j = 0; j < lottoNumbers.length - 1 - i; j++) {
                if (lottoNumbers[j] > lottoNumbers[j + 1]) {
                    int temp = lottoNumbers[j];
                    lottoNumbers[j] = lottoNumbers[j + 1];
                    lottoNumbers[j + 1] = temp;
                }
            }
        }

        System.out.print("최종 로또 번호 (오름차순): [");
        for (int i = 0; i < lottoNumbers.length; i++) {
            System.out.printf("%2d%s", lottoNumbers[i], (i < 5 ? ", " : "]\n"));
        }
    }
}

