class ShoppingCart {
    private String customerName;
    private CartItem[] items;
    private int itemCount;

    public ShoppingCart(String customerName, int maxCapacity) {
        this.customerName = customerName;
        this.items = new CartItem[maxCapacity];
        this.itemCount = 0;
    }

    public boolean addItem(CartItem item) {
        if (itemCount >= items.length) {
            System.out.printf("[%s 고객님] 장바구니 한도(%d개)를 초과하여 담을 수 없습니다.\n", customerName, items.length);
            return false;
        }
        items[itemCount++] = item;
        return true;
    }

    public int calculateGrandTotal() {
        int grandTotal = 0;
        for (int i = 0; i < itemCount; i++) grandTotal += items[i].getItemTotal();
        return grandTotal;
    }

    public void printCartSummary() {
        System.out.printf("=== [%s 고객님의 쇼핑 장바구니 내역] ===\n", customerName);
        for (int i = 0; i < itemCount; i++) System.out.println((i + 1) + ". " + items[i]);
        System.out.println("-----------------------------------------------------");
        System.out.printf("총 결제 예정 금액: %,d원\n", calculateGrandTotal());
