package day05;

class BankAccount {
    protected String accountNumber;
    protected String owner;
    protected int balance;

    public BankAccount(String accountNumber, String owner, int balance) {
        this.accountNumber = accountNumber;
        this.owner = owner;
        this.balance = balance;
    }

    public void deposit(int amount) {
        this.balance += amount;
        System.out.printf("[%s] %,d원 입금 완료 (잔액: %,d원)\n", accountNumber, amount, balance);
    }

    public boolean withdraw(int amount) {
        if (balance >= amount) {
            this.balance -= amount;
            System.out.printf("[%s] %,d원 출금 완료 (잔액: %,d원)\n", accountNumber, amount, balance);
            return true;
        }
        System.out.printf("[%s] 출금 실패: 잔액 부족\n", accountNumber);
        return false;
    }

    @Override
    public String toString() {
        return String.format("[%s] 소유주: %s | 잔액: %,d원", accountNumber, owner, balance);
    }
}

class SavingsAccount extends BankAccount {
    private double interestRate;

    public SavingsAccount(String accountNumber, String owner, int balance, double interestRate) {
        super(accountNumber, owner, balance);
        this.interestRate = interestRate;
    }

    public void applyAnnualInterest() {
        int interest = (int)(this.balance * this.interestRate);
        this.balance += interest;
        System.out.printf("[%s] 연이자 %,d원 지급 완료 (이율: %.1f%%, 잔액: %,d원)\n",
                accountNumber, interest, interestRate * 100, balance);
    }
}

class MinusAccount extends BankAccount {
    private int creditLimit;

    public MinusAccount(String accountNumber, String owner, int balance, int creditLimit) {
        super(accountNumber, owner, balance);
        this.creditLimit = creditLimit;
    }

    @Override
    public boolean withdraw(int amount) {
        if ((balance + creditLimit) >= amount) {
            this.balance -= amount;
            System.out.printf("[%s] 마이너스 출금 %,d원 성공 (현재 잔액: %,d원 / 대출한도: %,d원)\n",
                    accountNumber, amount, balance, creditLimit);
            return true;
        }
        System.out.printf("[%s] 마이너스 한도 초과 출금 불가!\n", accountNumber);
        return false;
    }
}

