class InsufficientBalanceException extends Exception {
    public InsufficientBalanceException(int currentBalance, int requestAmount) {
        super(String.format("잔액이 %,d원 부족합니다! (현재 잔액: %,d원, 요청 출금액: %,d원)",
                requestAmount - currentBalance, currentBalance, requestAmount));
    }
}

class AtmMachine {
    private int balance;

    public AtmMachine(int initialBalance) {
        this.balance = initialBalance;
    }

    public void withdraw(int amount) throws InsufficientBalanceException {
        if (amount > balance) {
            throw new InsufficientBalanceException(balance, amount);
        }
        balance -= amount;
        System.out.printf("💸 %,d원 출금 완료! (남은 잔액: %,d원)\n", amount, balance);
    }
}

