import java.util.*;

public class Problem2_WordFrequencyTest {
    public static void main(String[] args) {
        List<String> sales = Arrays.asList(
            "사과", "바나나", "사과", "딸기", "바나나", "사과", "포도", "딸기", "수박"
        );

        Set<String> uniqueFruits = new HashSet<>(sales);
        Map<String, Integer> salesCount = new HashMap<>();

        for (String fruit : sales) {
            salesCount.put(fruit, salesCount.getOrDefault(fruit, 0) + 1);
        }

        System.out.println("=== 과일 가게 판매 현황 분석 ===");
        System.out.printf("총 판매: %d건 | 고유 품목: %d종\n", sales.size(), uniqueFruits.size());
        salesCount.forEach((fruit, count) -> System.out.printf("  - %s: %d개 판매\n", fruit, count));

        String topFruit = "";
        int maxSales = 0;
        for (Map.Entry<String, Integer> entry : salesCount.entrySet()) {
            if (entry.getValue() > maxSales) {
                maxSales = entry.getValue();
                topFruit = entry.getKey();
            }
        }
        System.out.printf("\n>> 👑 베스트셀러: %s (%d개)\n", topFruit, maxSales);
    }
}

