package day07;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Predicate;

class Product {
    private String name;
    private String category;
    private int price;

    public Product(String name, String category, int price) {
        this.name = name;
        this.category = category;
        this.price = price;
    }

    public String getName() { return name; }
    public String getCategory() { return category; }
    public int getPrice() { return price; }

    @Override
    public String toString() {
        return String.format("[%s] %-12s : %,6d원", category, name, price);
    }
}

class ProductFilter {
    public static List<Product> filter(List<Product> list, Predicate<Product> condition) {
        List<Product> result = new ArrayList<>();
        for (Product p : list) {
            if (condition.test(p)) result.add(p);
        }
        return result;
    }

    public static void forEach(List<Product> list, Consumer<Product> action) {
        for (Product p : list) action.accept(p);
    }
}

public class Problem3_ProductFilterPipelineTest {
    public static void main(String[] args) {
        List<Product> catalog = List.of(
            new Product("기계식 키보드", "전자제품", 89000),
            new Product("자바 프로그래밍 입문", "도서", 28000),
            new Product("무선 버티컬 마우스", "전자제품", 45000),
            new Product("클린 코드", "도서", 32000),
            new Product("스마트 머그컵", "생활용품", 15000),
            new Product("27인치 4K 모니터", "전자제품", 350000)
        );

        // 1. 도서 카테고리 필터링
        System.out.println("[도서 카테고리 목록]");
        List<Product> books = ProductFilter.filter(catalog, p -> "도서".equals(p.getCategory()));
        ProductFilter.forEach(books, p -> System.out.println("📚 " + p));

        // 2. 10만원 미만 가성비 전자제품 복합 필터링
        System.out.println("\n[10만원 미만 가성비 전자제품]");
        List<Product> budget = ProductFilter.filter(catalog,
            p -> "전자제품".equals(p.getCategory()) && p.getPrice() < 100000);
        ProductFilter.forEach(budget, p -> System.out.println("⚡ " + p));
    }
}

